//! Rust source emitter for swift-stub-gen.
//!
//! Produces a self-contained `.rs` module that can be dropped into
//! `crates/libsystem-shims/src/darwin_stubs/` and wired into
//! `install_darwin_stubs`.
//!
//! # Generated layout
//!
//! ```text
//! // Auto-generated by swift-stub-gen …
//! use crate::table::ShimTable;
//!
//! pub struct SwiftUiStubs;
//! impl SwiftUiStubs {
//!     pub fn install(table: &mut ShimTable) { … }
//! }
//!
//! // Null stubs — single function + optional static data
//! extern "C" fn swift_null_stub() -> u64 { 0 }
//! static SWIFT_NULL_DATA: u64 = 0;
//! ```

use std::collections::HashSet;
use std::fmt::Write as _;

use crate::demangler;
use crate::extractor::ExtractedSymbol;

/// Options that control what the code generator emits.
#[derive(Debug, Clone)]
pub struct CodegenOptions {
    /// Base name for the generated struct (e.g. `"SwiftUi"` → `SwiftUiStubs`).
    pub struct_prefix: String,
    /// Source path or description included in the file header comment.
    pub source_desc: String,
    /// Generation timestamp (ISO date string).
    pub date: String,
    /// Whether to call `swift-demangle` for human-readable comments.
    pub demangle: bool,
    /// Emit stubs for re-exported symbols too (default: false).
    #[allow(dead_code)]
    pub include_reexports: bool,
    /// Emit stubs for data symbols (type metadata, witness tables).
    pub include_data_stubs: bool,
}

/// Generate the complete Rust module source for the given symbol list.
///
/// Only emits stubs for symbols that pass [`demangler::is_swift_mangled`].
/// Non-Swift symbols in the list are silently skipped.
pub fn generate(symbols: &[ExtractedSymbol], opts: &CodegenOptions) -> String {
    let struct_name = format!("{}Stubs", opts.struct_prefix);

    // Collect stubs, deduplicating by name.
    let mut seen: HashSet<&str> = HashSet::new();
    let mut fn_stubs: Vec<&ExtractedSymbol> = Vec::new();
    let mut data_stubs: Vec<&ExtractedSymbol> = Vec::new();

    for sym in symbols {
        if !demangler::is_swift_mangled(&sym.name) {
            continue;
        }
        if seen.contains(sym.name.as_str()) {
            continue;
        }
        seen.insert(&sym.name);
        if sym.is_data && opts.include_data_stubs {
            data_stubs.push(sym);
        } else if !sym.is_data {
            fn_stubs.push(sym);
        }
    }

    let total = fn_stubs.len() + data_stubs.len();
    let mut out = String::with_capacity(total * 120 + 1024);

    // ── File header ────────────────────────────────────────────
    write!(out, "// Auto-generated by swift-stub-gen.\n").ok();
    write!(out, "// Source:    {}\n", opts.source_desc).ok();
    write!(out, "// Date:      {}\n", opts.date).ok();
    write!(out, "// Stubs:     {} ({} fn, {} data)\n",
        total, fn_stubs.len(), data_stubs.len()).ok();
    write!(out, "//\n").ok();
    write!(out, "// DO NOT EDIT.  Re-run swift-stub-gen against the framework binary to update.\n").ok();
    write!(out, "//\n").ok();
    write!(out, "// Usage:\n").ok();
    write!(out, "//   swift-stub-gen [--demangle] <path/to/SwiftUI> -o swift_{}.rs\n",
        opts.struct_prefix.to_lowercase()).ok();
    write!(out, "//   # then drop into crates/libsystem-shims/src/darwin_stubs/\n").ok();
    write!(out, "\n").ok();
    write!(out, "use crate::table::ShimTable;\n").ok();
    write!(out, "\n").ok();

    // ── Struct + install() ─────────────────────────────────────
    write!(out, "pub struct {};\n", struct_name).ok();
    write!(out, "impl {} {{\n", struct_name).ok();
    write!(out, "    pub fn install(table: &mut ShimTable) {{\n").ok();

    if !fn_stubs.is_empty() {
        write!(out, "        // Function stubs — all route through swift_null_stub (returns 0).\n").ok();
        write!(out, "        let fn_addr = swift_null_stub as u64;\n").ok();
        for sym in &fn_stubs {
            let comment = build_comment(sym, opts.demangle);
            write!(out,
                "        table.register({name:?}, fn_addr, {comment:?});\n",
                name = sym.name,
                comment = comment,
            ).ok();
        }
    }

    if !data_stubs.is_empty() {
        write!(out, "\n        // Data stubs — point into the null-data static.\n").ok();
        write!(out, "        let data_addr = &SWIFT_NULL_DATA as *const u64 as u64;\n").ok();
        for sym in &data_stubs {
            let comment = build_comment(sym, opts.demangle);
            write!(out,
                "        table.register({name:?}, data_addr, {comment:?});\n",
                name = sym.name,
                comment = comment,
            ).ok();
        }
    }

    write!(out, "        log::debug!(\"{struct_name}: registered {total} Swift stubs\");\n",
        struct_name = struct_name, total = total).ok();
    write!(out, "    }}\n").ok();   // close install
    write!(out, "}}\n").ok();       // close impl

    // ── Null implementations ───────────────────────────────────
    write!(out, "\n").ok();
    write!(out, "// All Swift function stubs route here.  The stub returns 0 / nullptr,\n").ok();
    write!(out, "// which is the safest no-op for Swift calling-convention functions when\n").ok();
    write!(out, "// the caller checks for nil before dereferencing.\n").ok();
    write!(out, "extern \"C\" fn swift_null_stub() -> u64 {{ 0 }}\n").ok();

    if !data_stubs.is_empty() {
        write!(out, "\n").ok();
        write!(out, "// Null backing store for data symbol stubs (type metadata, witness tables).\n").ok();
        write!(out, "static SWIFT_NULL_DATA: u64 = 0;\n").ok();
    }

    out
}

/// Build the description string for a shim registration.
fn build_comment(sym: &ExtractedSymbol, try_demangle: bool) -> String {
    let category = demangler::classify(&sym.name);
    if try_demangle {
        if let Some(human) = demangler::demangle(&sym.name) {
            return format!("{category}: {human}");
        }
    }
    format!("{category}: {name}", name = sym.name)
}

/// Derive a `struct_prefix` from a framework path.
///
/// `/Applications/Xcode.app/…/SwiftUI.framework/SwiftUI` → `"SwiftUi"`
///
/// The prefix is PascalCase: `SwiftUI` → `SwiftUi` so the struct name
/// `SwiftUiStubs` is a valid Rust identifier (no consecutive uppercase runs).
pub fn prefix_from_path(path: &std::path::Path) -> String {
    // Try to find the `.framework` component and use what comes before it.
    let name = path
        .components()
        .rev()
        .find_map(|c| {
            let s = c.as_os_str().to_string_lossy();
            if s.ends_with(".framework") {
                Some(s.trim_end_matches(".framework").to_owned())
            } else {
                None
            }
        })
        .or_else(|| path.file_stem().map(|s| s.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "Swift".to_owned());

    // Convert to PascalCase-safe identifier: split on `_`/` ` and capitalise.
    // Also collapse consecutive uppercase runs to avoid `SWIFTUI` → need at
    // most one uppercase char per "word" after the first character.
    let mut result = String::new();
    let mut new_word = true;
    let mut prev_was_lower = false;
    for ch in name.chars() {
        if ch == '_' || ch == '-' || ch == ' ' {
            new_word = true;
            prev_was_lower = false;
        } else if new_word {
            result.extend(ch.to_uppercase());
            new_word = false;
            prev_was_lower = ch.is_lowercase();
        } else if ch.is_uppercase() && prev_was_lower {
            // Lowercase → uppercase transition: start of a new word (e.g. `UI` in `SwiftUI`).
            result.extend(ch.to_uppercase());
            prev_was_lower = false;
        } else if ch.is_uppercase() {
            // Consecutive uppercase run: fold to lowercase (e.g. second `I` in `UI`).
            result.push(ch.to_lowercase().next().unwrap_or(ch));
            prev_was_lower = false;
        } else {
            result.push(ch);
            prev_was_lower = ch.is_lowercase();
        }
    }
    if result.is_empty() {
        result.push_str("Swift");
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::extractor::{ExtractedSymbol, SymbolKind};

    fn make_sym(name: &str) -> ExtractedSymbol {
        ExtractedSymbol {
            name: name.to_string(),
            kind: SymbolKind::Regular,
            is_data: false,
        }
    }

    #[test]
    fn test_prefix_from_path_framework() {
        let p = std::path::Path::new("/S/L/Frameworks/SwiftUI.framework/SwiftUI");
        assert_eq!(prefix_from_path(p), "SwiftUi");
    }

    #[test]
    fn test_prefix_from_path_stem() {
        let p = std::path::Path::new("/tmp/RegexBuilder");
        assert_eq!(prefix_from_path(p), "RegexBuilder");
    }

    #[test]
    fn test_generate_empty() {
        let opts = CodegenOptions {
            struct_prefix: "SwiftUi".to_string(),
            source_desc: "/tmp/SwiftUI".to_string(),
            date: "2026-04-03".to_string(),
            demangle: false,
            include_reexports: false,
            include_data_stubs: true,
        };
        let src = generate(&[], &opts);
        assert!(src.contains("SwiftUiStubs"));
        assert!(src.contains("pub fn install"));
    }

    #[test]
    fn test_generate_fn_stub() {
        let syms = vec![make_sym("_$s7SwiftUI4TextVACycfC")];
        let opts = CodegenOptions {
            struct_prefix: "SwiftUi".to_string(),
            source_desc: "test".to_string(),
            date: "2026-04-03".to_string(),
            demangle: false,
            include_reexports: false,
            include_data_stubs: true,
        };
        let src = generate(&syms, &opts);
        assert!(src.contains("_$s7SwiftUI4TextVACycfC"));
        assert!(src.contains("swift_null_stub"));
        assert!(!src.contains("SWIFT_NULL_DATA")); // no data stubs
    }

    #[test]
    fn test_generate_data_stub() {
        let mut sym = make_sym("_$s7SwiftUI4TextVMa");
        sym.is_data = true;
        let opts = CodegenOptions {
            struct_prefix: "SwiftUi".to_string(),
            source_desc: "test".to_string(),
            date: "2026-04-03".to_string(),
            demangle: false,
            include_reexports: false,
            include_data_stubs: true,
        };
        let src = generate(&[sym], &opts);
        assert!(src.contains("SWIFT_NULL_DATA"));
    }

    #[test]
    fn test_non_swift_symbols_skipped() {
        let syms = vec![
            make_sym("_printf"),
            make_sym("_NSString"),
            make_sym("_$s7SwiftUI4ViewP"),
        ];
        let opts = CodegenOptions {
            struct_prefix: "SwiftUi".to_string(),
            source_desc: "test".to_string(),
            date: "2026-04-03".to_string(),
            demangle: false,
            include_reexports: false,
            include_data_stubs: true,
        };
        let src = generate(&syms, &opts);
        // Only the Swift symbol should appear
        assert!(src.contains("_$s7SwiftUI4ViewP"));
        assert!(!src.contains("_printf"));
        assert!(!src.contains("_NSString"));
    }

    #[test]
    fn test_deduplicate() {
        let syms = vec![
            make_sym("_$s7SwiftUI4ViewP"),
            make_sym("_$s7SwiftUI4ViewP"), // duplicate
        ];
        let opts = CodegenOptions {
            struct_prefix: "SwiftUi".to_string(),
            source_desc: "test".to_string(),
            date: "2026-04-03".to_string(),
            demangle: false,
            include_reexports: false,
            include_data_stubs: true,
        };
        let src = generate(&syms, &opts);
        // There should be exactly one `table.register("_$s7SwiftUI4ViewP"` call.
        assert_eq!(src.matches("table.register(\"_$s7SwiftUI4ViewP\"").count(), 1);
    }
}
